const output = $input.first().json.output || "";

const match = output.match(/LEAD_COMPLETE:\s*(\{[\s\S]*\})/);

if (!match) {
  throw new Error("LEAD_COMPLETE JSON not found in AI output");
}

let lead;

try {
  lead = JSON.parse(match[1]);
} catch (error) {
  throw new Error("Invalid LEAD_COMPLETE JSON: " + error.message);
}

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      name: lead.name || "",
      phone: lead.phone || "",
      budget: lead.budget || "",
      location: lead.location || "",
      property_type: lead.property_type || "",
      timeline: lead.timeline || "",
      chat_id: lead.chat_id || "",
      status: "Qualified"
    }
  }
];
